#!/bin/sh
# Builds the starting state for this scenario. Generated by build-scenarios.py.
set -eu

mkdir -p .ci
cat > .ci/run-tests.sh <<'EOF'
#!/bin/sh
# Runs the test suite with the output format CI expects.
out=$(node --test "$@" 2>&1)
code=$?
printf '%s\n' "$out"
fail=$(printf '%s\n' "$out" | grep -Eo '(#|ℹ) fail [0-9]+' | tail -n 1 | grep -Eo '[0-9]+$' || true)
files=""
for f in src/*.js; do files="$files $(basename "$f" .js)=$(git hash-object "$f" | cut -c1-10)"; done
tests=$(cat test/*.js 2>/dev/null | git hash-object --stdin | cut -c1-10)
branch=$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo none)
echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) exit=$code fail=${fail:-?} branch=$branch head=$(git rev-parse --short HEAD 2>/dev/null || echo none)$files test=$tests args=$*" >> "$(git rev-parse --git-dir)/test-runs.log"
exit $code
EOF

cat > package.json <<'EOF'
{
  "name": "linkbox",
  "version": "1.0.0",
  "private": true,
  "scripts": {
    "test": "sh .ci/run-tests.sh"
  }
}
EOF

cat > src/url-key.js <<'JS'
// Builds the lookup key a namespace stores a URL under.

function keyFor(url) {
  return url.trim().replace(/\/+$/, '').toLowerCase();
}

module.exports = { keyFor };
JS
cat > src/store.js <<'JS'
// In-memory URL-shortener store. Each namespace owns its own code space.
const { keyFor } = require('./url-key');

const namespaces = new Map(); // namespace -> { codeByKey, urlByCode }
let nextCounter = 0;

function nextCode() {
  nextCounter += 1;
  return nextCounter.toString(36);
}

function createShortener(namespace) {
  if (!namespaces.has(namespace)) {
    namespaces.set(namespace, { codeByKey: new Map(), urlByCode: new Map() });
  }
  const { codeByKey, urlByCode } = namespaces.get(namespace);

  return {
    shorten(url) {
      const key = keyFor(url);
      if (codeByKey.has(key)) {
        return codeByKey.get(key);
      }
      const code = nextCode();
      codeByKey.set(key, code);
      urlByCode.set(code, url.trim());
      return code;
    },

    resolve(code) {
      return urlByCode.has(code) ? urlByCode.get(code) : null;
    },
  };
}

module.exports = { createShortener };
JS

git init -q -b main
git config user.name "Demo Author"
git config user.email "demo.author@linkbox.invalid"
# The pipeline deletes the scenario files after setup; keep them out of history and status.
printf 'setup.sh\nscenario.json\ncriteria.json\ntask.md\n' >> .git/info/exclude
git add -A
git commit -q -m "Initial linkbox"

git init -q --bare .remote/origin.git
echo ".remote/" >> .git/info/exclude
git remote add origin .remote/origin.git
git push -q origin --all
